import {truthBadge} from './outpost-presentation.js';
import {t,copy} from './strings.js';
import {MODULES,GRID,layoutEffects,placementEffects,distance,validLayout} from './base-design.js';
import {SITE_IDS,mapPoint} from './landing-sites.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const MODULE_ICONS={shelter:'🛡️',greenhouse:'🌱',solar1:'☀️',solar2:'☀️',water:'💧',garage:'🚙'};
export const moduleName=id=>t('module'+id[0].toUpperCase()+id.slice(1));
export function siteMapHTML(selected){const sites=copy('sites');return `<figure class="mars-map"><img src="./assets/mars-viking.jpg" width="1440" height="720" alt="${t('mapAlt')}">${SITE_IDS.map((id,i)=>{const s=sites[id],p=mapPoint(s.lat,s.lon);return `<button type="button" class="map-pin" data-site="${id}" style="left:${p.x}%;top:${p.y}%" aria-label="${esc(s.name+' · '+s.coordinates)}" aria-pressed="${id===selected}">${i+1}</button>`;}).join('')}</figure><p class="map-credit"><a href="https://space.jpl.nasa.gov/tmaps/mars.html" target="_blank" rel="noopener">${t('mapCredit')}</a> · ${t('mapCreditDetail')}</p>`;}
export function siteCardsHTML(selected){const sites=copy('sites');return `<div class="site-options">${SITE_IDS.map((id,i)=>{const s=sites[id];return `<article class="site-card ${id===selected?'selected':''}"><button class="site-select" data-site="${id}" aria-pressed="${id===selected}"><strong>${i+1} · ${esc(s.name)}</strong><small>${esc(s.coordinates)}</small></button><p>${esc(s.story)}</p><details class="learn-more"><summary>${t('learnMore')}</summary><p class="simple-note">${truthBadge('game')} ${t('siteRule'+id[0].toUpperCase()+id.slice(1))}</p><p>${truthBadge('real')} ${esc(s.fact)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener">${t('source')}</a><a href="https://trek.nasa.gov/mars/" target="_blank" rel="noopener">${t('trekLink')}</a><a href="${esc(s.coordinateSource)}" target="_blank" rel="noopener">${t('siteCoordinate',{coordinates:esc(s.coordinates)})}</a></details></article>`;}).join('')}</div>`;}
export function baseGridHTML(layout,{edit=false,cursor=12}={}){return `<div class="base-grid" role="group" aria-label="${t('baseMap')}">${Array.from({length:20},(_,tile)=>{const module=MODULES.find(k=>layout[k]===tile),home=tile===GRID.habitat,wind=tile%5===4,label=t('designTile',{row:Math.floor(tile/5)+1,column:tile%5+1,module:home?t('designHome'):module?moduleName(module):t('designEmpty'),wind:wind?t('designWind'):''});return `<${edit?'button':'div'} class="base-tile ${home?'habitat-tile':''} ${wind?'wind-tile':''}" ${edit?`type="button" data-tile="${tile}" tabindex="${tile===cursor?0:-1}"`:'role="img"'} aria-label="${esc(label)}"><span aria-hidden="true">${home?'⌂':module?MODULE_ICONS[module]:wind?'≈':'·'}</span>${module?`<small>${t('tile'+module[0].toUpperCase()+module.slice(1))}</small>`:home?`<small>${t('tileHome')}</small>`:''}</${edit?'button':'div'}>`;}).join('')}</div>`;}
export function layoutHint(layout,module){const e=placementEffects(layout);return module==='shelter'?t(e.shelterFar?'shelterFar':'shelterNear'):module==='greenhouse'||module==='water'?t(e.foodBonus?'greenhouseNear':'greenhouseFar'):module==='garage'?t(e.roverSafe?'garageNear':'garageFar'):t('panelsHint');}
export function designEffectsHTML(layout){if(!validLayout(layout))return `<p>${t('designIncomplete')}</p>`;const e=layoutEffects(layout);return `<p class="simple-note">${t('layoutSummary',{distance:distance(layout.shelter,GRID.habitat),windy:e.windyPanels,near:e.nearPanels})}</p><ul class="design-effects">${['shelter','solar1','greenhouse','garage'].map(k=>`<li>${layoutHint(layout,k)}</li>`).join('')}</ul>`;}
export function designEditorHTML(layout,selected,cursor){return `<div class="design-content"><button class="text-button" data-action="back-sites">${t('setupBack')}</button><h2>${t('designTitle')}</h2><details class="learn-more"><summary>${t('howToPlay')}</summary><p>${t('designIntro')}</p><p class="simple-note">${t('designControls')}</p></details><div class="module-picker" role="group" aria-label="${t('baseDesign')}">${MODULES.map(k=>`<button class="chip-button" data-module="${k}" draggable="false" aria-pressed="${selected===k}"><span aria-hidden="true">${MODULE_ICONS[k]}</span>${moduleName(k)}</button>`).join('')}</div>${baseGridHTML(layout,{edit:true,cursor})}<p id="designStatus" role="status">${t(validLayout(layout)?'designReady':'designIncomplete')}</p><details class="rules-detail"><summary>${t('howItWorks')}</summary>${truthBadge('game')}<p>${t('designGame')}</p>${designEffectsHTML(layout)}</details><div class="panel-actions"><button class="chip-button" data-action="pip-layout">${t('designPip')}</button><button class="chip-button" data-action="reset-layout">${t('designReset')}</button></div></div><footer class="setup-footer"><button class="primary" data-action="launch" ${validLayout(layout)?'':'disabled'}>${t('designLaunch')}</button><button class="chip-button" data-action="pip-launch">${t('pipChoice')}</button></footer>`;}
